package fr.loto.cartons;
import android.app.*;import android.os.*;import android.content.*;import android.net.Uri;import android.view.*;import android.widget.*;import org.json.*;import java.util.*;
public class MainActivity extends Activity {
 Game game=new Game(); LinearLayout root,cards,entry; TextView input;String digits="";static final int PICK=12; boolean startupPromptVisible=true; final Handler promptHandler=new Handler(Looper.getMainLooper());
 @Override public void onCreate(Bundle b){super.onCreate(b);getWindow().addFlags(128);load();render();promptHandler.postDelayed(()->{startupPromptVisible=false;render();},30000);}
 TextView text(String s,int size){TextView t=new TextView(this);t.setText(s);t.setTextSize(size);t.setGravity(Gravity.CENTER);t.setPadding(5,8,5,8);return t;}
 Button button(String s,Runnable r){Button b=new Button(this);b.setText(s);b.setAllCaps(false);b.setOnClickListener(v->r.run());return b;}
 void render(){root=new LinearLayout(this);root.setOrientation(1);setContentView(root);LinearLayout modes=new LinearLayout(this);root.addView(modes);for(int i=1;i<=3;i++){final int m=i;Button b=button(i==1?"1 LIGNE":i==2?"2 LIGNES":"CARTON PLEIN",()->{game.mode=m;save();render();});b.setEnabled(game.mode!=i);modes.addView(b,new LinearLayout.LayoutParams(0,60,1));}
 Button browse=button("📂 PARCOURIR MES PDF — TÉLÉCHARGEMENTS",()->openPdfPicker());browse.setTextSize(17);browse.setBackgroundTintList(android.content.res.ColorStateList.valueOf(0xff1565c0));browse.setTextColor(0xffffffff);root.addView(browse,new LinearLayout.LayoutParams(-1,68));
 if(startupPromptVisible){LinearLayout banner=new LinearLayout(this);banner.setOrientation(0);banner.setBackgroundColor(0xfffff3cd);TextView hint=text("Importer tes cartons PDF depuis la tablette",15);banner.addView(hint,new LinearLayout.LayoutParams(0,54,1));banner.addView(button("CHOISIR PDF",()->openPdfPicker()),new LinearLayout.LayoutParams(-2,54));banner.addView(button("X",()->{startupPromptVisible=false;render();}),new LinearLayout.LayoutParams(54,54));root.addView(banner);}
 boolean wide=getResources().getConfiguration().orientation==2;LinearLayout body=new LinearLayout(this);body.setOrientation(wide?0:1);root.addView(body,new LinearLayout.LayoutParams(-1,0,1));
 ScrollView scroll=new ScrollView(this);cards=new LinearLayout(this);cards.setOrientation(1);scroll.addView(cards);body.addView(scroll,new LinearLayout.LayoutParams(wide?0:-1,wide?-1:0,7));
 entry=new LinearLayout(this);entry.setOrientation(1);body.addView(entry,new LinearLayout.LayoutParams(wide?0:-1,wide?-1:0,3));
 LinearLayout actions=new LinearLayout(this);entry.addView(actions);
 actions.addView(button("DÉMARQUER",()->new AlertDialog.Builder(this).setTitle("Effacer tous les tirages ?").setNegativeButton("Annuler",null).setPositiveButton("Confirmer",(d,w)->{game.clear();save();render();}).show()),new LinearLayout.LayoutParams(-1,55));

 input=text(digits.isEmpty()?"Numéro (1 à 90)":digits,23);entry.addView(input);
 LinearLayout pad=new LinearLayout(this);pad.setOrientation(1);entry.addView(pad,new LinearLayout.LayoutParams(-1,0,1));String[][] keys={{"1","2","3"},{"4","5","6"},{"7","8","9"},{"⌫","0","OK"}};for(String[] line:keys){LinearLayout row=new LinearLayout(this);pad.addView(row,new LinearLayout.LayoutParams(-1,0,1));for(String key:line)row.addView(button(key,()->key(key)),new LinearLayout.LayoutParams(0,-1,1));}
 LinearLayout edits=new LinearLayout(this);entry.addView(edits);edits.addView(button("CORRIGER",()->numberDialog("Ancien numéro",old->numberDialog("Nouveau numéro",n->{try{game.replace(old,n);save();render();}catch(Exception e){toast(e.getMessage());}}))),new LinearLayout.LayoutParams(0,55,1));edits.addView(button("SUPPRIMER",()->numberDialog("Numéro à supprimer",n->{game.remove(n);save();render();})),new LinearLayout.LayoutParams(0,55,1));
 entry.addView(text("Tirages : "+game.drawn.toString(),14));showCards();checkWin();}
 void key(String k){if(k.equals("⌫")){if(!digits.isEmpty())digits=digits.substring(0,digits.length()-1);}else if(k.equals("OK")){if(!digits.isEmpty()){int n=Integer.parseInt(digits);if(n>=1&&n<=90&&!game.drawn.contains(n)){game.add(n);digits="";save();render();return;}toast("Numéro invalide ou déjà tiré");}}else if(digits.length()<2)digits+=k;input.setText(digits.isEmpty()?"Numéro (1 à 90)":digits);}
 interface Callback{void accept(int n);}void numberDialog(String title,Callback cb){EditText e=new EditText(this);e.setInputType(2);new AlertDialog.Builder(this).setTitle(title).setView(e).setNegativeButton("Annuler",null).setPositiveButton("OK",(d,w)->{try{cb.accept(Integer.parseInt(e.getText().toString()));}catch(Exception ex){toast("Numéro invalide");}}).show();}
 void showCards(){ArrayList<Game.Card> list=new ArrayList<>(game.cards);list.sort((a,b)->Integer.compare(game.missing(a),game.missing(b)));if(list.isEmpty())cards.addView(text("Importer un PDF de cartons",22));for(int i=0;i<list.size();i++)cards.addView(cardView(list.get(i),i==0));}
 LinearLayout cardView(Game.Card c,boolean large){LinearLayout box=new LinearLayout(this);box.setOrientation(1);box.setPadding(8,8,8,15);box.setBackgroundColor(large?0xffdbeafe:0xffeeeeee);box.addView(text("CARTON "+c.id+" — "+game.missing(c)+" manquant(s)",large?23:17));for(int[] line:c.grid){LinearLayout row=new LinearLayout(this);box.addView(row);for(int n:line){TextView cell=text(n==0?"":""+n,large?21:16);cell.setBackgroundColor(n!=0&&game.drawn.contains(n)?0xffa7e8b4:0xffffffff);row.addView(cell,new LinearLayout.LayoutParams(0,large?55:42,1));}}return box;}
 void checkWin(){for(Game.Card c:game.cards)if(game.winner(c)&&!game.acknowledged.contains(game.winKey(c))){new AlertDialog.Builder(this).setTitle("GAGNANT ! Carton "+c.id).setView(cardView(c,true)).setCancelable(false).setPositiveButton("VÉRIFICATION OK",(d,w)->{game.acknowledged.add(game.winKey(c));save();render();}).show();break;}}
 void openPdfPicker(){try{Intent i=new Intent(Intent.ACTION_OPEN_DOCUMENT);i.addCategory(Intent.CATEGORY_OPENABLE);i.setType("application/pdf");i.addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION|Intent.FLAG_GRANT_PERSISTABLE_URI_PERMISSION);startActivityForResult(i,PICK);}catch(Exception e){try{Intent i=new Intent(Intent.ACTION_GET_CONTENT);i.setType("application/pdf");i.addCategory(Intent.CATEGORY_OPENABLE);startActivityForResult(Intent.createChooser(i,"Choisir un PDF dans la tablette"),PICK);}catch(Exception ex){new AlertDialog.Builder(this).setTitle("Explorateur indisponible").setMessage(ex.getMessage()).setPositiveButton("OK",null).show();}}}
 void toast(String s){Toast.makeText(this,s,Toast.LENGTH_LONG).show();}
 @Override protected void onActivityResult(int request,int result,Intent data){super.onActivityResult(request,result,data);if(request!=PICK||result!=RESULT_OK||data==null)return;Uri uri=data.getData();if(uri==null){toast("Aucun fichier sélectionné");return;}try{getContentResolver().takePersistableUriPermission(uri,Intent.FLAG_GRANT_READ_URI_PERMISSION);}catch(Exception ignored){}new Thread(()->{try{ArrayList<Game.Card> imported=PdfImporter.read(this,uri);runOnUiThread(()->{int added=0;for(Game.Card c:imported){boolean exists=false;for(Game.Card x:game.cards)if(x.id.equals(c.id))exists=true;if(!exists){game.cards.add(c);added++;}}save();render();toast(added+" cartons importés. Vérifie leur contenu.");});}catch(Exception e){runOnUiThread(()->new AlertDialog.Builder(this).setTitle("Import impossible").setMessage(e.getMessage()).setPositiveButton("OK",null).show());}}).start();}
 void save(){try{JSONObject o=new JSONObject();o.put("mode",game.mode);JSONArray cs=new JSONArray();for(Game.Card c:game.cards){JSONObject j=new JSONObject();j.put("id",c.id);JSONArray rows=new JSONArray();for(int[] row:c.grid){JSONArray nums=new JSONArray();for(int n:row)nums.put(n);rows.put(nums);}j.put("grid",rows);cs.put(j);}o.put("cards",cs);o.put("drawn",new JSONArray(game.drawn));o.put("ack",new JSONArray(game.acknowledged));getPreferences(0).edit().putString("state",o.toString()).apply();}catch(Exception ignored){}}
 void load(){try{JSONObject o=new JSONObject(getPreferences(0).getString("state","{}"));game.mode=o.optInt("mode",1);JSONArray cs=o.optJSONArray("cards");if(cs!=null)for(int i=0;i<cs.length();i++){JSONObject j=cs.getJSONObject(i);Game.Card c=new Game.Card(j.getString("id"));JSONArray rows=j.getJSONArray("grid");for(int r=0;r<3;r++)for(int k=0;k<9;k++)c.grid[r][k]=rows.getJSONArray(r).getInt(k);game.cards.add(c);}JSONArray d=o.optJSONArray("drawn");if(d!=null)for(int i=0;i<d.length();i++)game.drawn.add(d.getInt(i));JSONArray a=o.optJSONArray("ack");if(a!=null)for(int i=0;i<a.length();i++)game.acknowledged.add(a.getString(i));}catch(Exception ignored){}}
}